import { my_slot_booking } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import CancelBooking from "@/components/SloatBooking/Popups/CancelBooking.vue";
import SnackBar from "@/components/SnackBar.vue";
import { formatdisplayDate } from "@/JsonFiles/DateFormate.js";
export default {
  props: {
    historyDialog: Boolean
  },
  components: {
    CancelBooking,
    SnackBar
  },
  data() {
    return {
      tableData: [],
      tableLoading: false,
      headers: [{
        title: "Name",
        value: "resource_name",
        sortable: false
      }, {
        title: "Booked Slot",
        value: "booked_slot",
        sortable: false
      }, {
        title: "Booked On",
        value: "booked_date_on",
        sortable: false
      }, {
        title: "Comments",
        value: "booking_comments",
        sortable: false
      }, {
        title: "Category",
        value: "booking_category_name",
        sortable: false
      }, {
        title: "Status",
        value: "booking_status",
        sortable: false
      }

      // { text: "Actions", value: "actions", sortable: false },
      ],
      fixed: true,
      height: 0,
      cancelDialog: false,
      componentCheck: 0,
      rowInfo: {},
      SnackBarComponent: {}
    };
  },
  watch: {
    historyDialog: {
      async handler() {
        if (this.historyDialog == true) {
          this.height = window.innerHeight - 250;
          this.tableLoading = false;
          await this.fetch_booking_history();
        }
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    success_msg(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.cancelDialog = false;
      this.fetch_booking_history();
    },
    error_msg(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    cancel_booking(item) {
      this.cancelDialog = true;
      this.componentCheck = 1;
      this.rowInfo = item;
    },
    async fetch_booking_history() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(my_slot_booking, {
          input: {
            user_id: data.user.user_id,
            limit: 100,
            nextToken: null
          }
        }));
        var response = JSON.parse(result.data.my_slot_booking);
        this.tableData = [];
        this.tableLoading = false;
        if (response.Status == "SUCCESS") {
          this.tableData = response.data;
          // console.log(this.tableData);
          // this.tableData = response.data;
        } else {}
      } catch (error) {
        this.tableData = [];
      }
    },
    get_date(val) {
      var data = formatdisplayDate(val);
      return data;
    },
    convert_time(value) {
      const epochTime = value; // Replace this number with your epoch time
      const date = new Date(epochTime * 1000); // Convert seconds to milliseconds

      const options = {
        hour12: true,
        // Set to true for 12-hour format
        hour: "numeric",
        minute: "numeric"
      };
      const formattedTime = date.toLocaleString("en-US", options);
      return formattedTime;
    }
  }
};
